-- SECURITY DEFINER; API roles that may call it: service_role
CREATE OR REPLACE FUNCTION public.seed_challenge_point_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.scoring = 'points'
     and new.community_id is not null
     and not exists (select 1 from public.point_rules where challenge_id = new.id)
  then
    insert into public.point_rules
      (community_id, challenge_id, kind, label, points, threshold, max_points, position, is_active)
    select community_id, new.id, kind, label, points, threshold, max_points, position, is_active
    from public.point_rules
    where community_id = new.community_id and challenge_id is null;
  end if;
  return new;
end;
$function$;
